// === Tab: mySketch ===
//Attractor?_12.0

let N = 1000 ; let M = 3 ; let V = 1 ; let K = 0.001 ; let R = 100 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let dX[] = new Array(N) ; let dY[] = new Array(N) ; 
let CX[] = new Array(M) ; let CY[] = new Array(M) ; let I ; let RR ; let RRR ; let A ; let L ;
let PX ; let PY ; let PZ ; let PA ; let BX ; let BY ;

function setup(){

  createCanvas(600, 600) ; noSmooth() ; background(0) ; stroke(255) ; fill(255) ;

  for  ( I = 0 ; I < M ; I++ ){
    CX[I] = R*cos(I*2*PI/M) ; CY[I] = R*sin(I*2*PI/M) ;
  }
  RR = R*sin(PI/M) ; RRR = R*cos(PI/M) ;

  X[0] = random(-10,+10) ; Y[0] = random(-10,+10) ; 
  A = random(-PI,+PI) ; dX[0] = V*cos(A) ; dY[0] = V*sin(A) ;
  for ( I = 1 ; I < N ; I++ ){ 
    X[I] = X[0] ; Y[I] = Y[0] ; dX[I] = dX[0] ; dY[I] = dY[0] ; 
  }

}// setup()

function draw(){

  background(0) ;

  for ( I = 0 ; I < M ; I++ ){
    L = sqrt(pow(X[0]-CX[I],2)+pow(Y[0]-CY[I],2)) ;
    if ( L < RR ){
      dX[0] = dX[0] + (K*(RR-L)*(X[0]-CX[I])/L) ; 
      dY[0] = dY[0] + (K*(RR-L)*(Y[0]-CY[I])/L) ; 
    }
  }
  L = sqrt(pow(X[0],2)+pow(Y[0],2)) ;
  if ( L > RRR ){
    dX[0] = dX[0] - (K*(L-RRR)*X[0]/L) ; 
    dY[0] = dY[0] - (K*(L-RRR)*Y[0]/L) ; 
  }
  L = sqrt(pow(dX[0],2)+pow(dY[0],2)) ;
  if ( L > 0 ){ dX[0] = dX[0]*V/L ; dY[0] = dY[0]*V/L ; }
  X[0] = X[0] + dX[0] ; Y[0] = Y[0] + dY[0] ;

  for ( I = N-1 ; I > 0 ; I-- ){
    A = atan(dY[I]/dX[I]) ; if ( dX[I] < 0 ){ A = A + PI ; }
    PX = (X[I]+(R*2))*cos(A) ; PY = (X[I]+(R*2))*sin(A) ; PZ = Y[I] ;
    PX = PX+300 ; PY = (PY*cos(PA))-(PZ*sin(PA))+300 ;
    if ( I < N-1 ){ line(PX,PY,BX,BY) ; }
    BX = PX ; BY = PY ; X[I] = X[I-1] ; Y[I] = Y[I-1] ; dX[I] = dX[I-1] ; dY[I] = dY[I-1] ; 
  }
  A = atan(dY[0]/dX[0]) ; if ( dX[0] < 0 ){ A = A + PI ; }
  PX = (X[0]+(R*2))*cos(A) ; PY = (X[0]+(R*2))*sin(A) ; PZ = Y[0] ;
  PX = PX+300 ; PY = (PY*cos(PA))-(PZ*sin(PA))+300 ;
  ellipse(PX,PY,10,10) ;
  PA = PA + 0.01 ;

}// draw() ;

function mousePressed(){ setup() ; }

